create or replace function public.admin_user_rows() returns table ( id uuid, email text, full_name text, company text, role text, plan text, created_at timestamptz, orders bigint, spend_minor bigint ) language sql stable security definer set search_path = public as $$ select p.id, p.email, p.full_name, p.company, p.role::text, p.plan, p.created_at, coalesce(tallied.orders, 0)::bigint, coalesce(tallied.spend_minor, 0)::bigint from public.profiles p left join ( select o.user_id, count(*) as orders, sum(o.total_minor) as spend_minor from public.orders o where o.status not in ('cancelled', 'draft') group by o.user_id ) as tallied on tallied.user_id = p.id order by p.created_at desc, p.id asc; $$;
comment on function public.admin_user_rows() is 'Every account with its order count and lifetime spend, counted in one pass. Replaces reading every profile and every order and filtering one against the other.';
revoke all on function public.admin_user_rows() from public;
revoke all on function public.admin_user_rows() from anon;
revoke all on function public.admin_user_rows() from authenticated;
